package com.quincaisoft.workers.web;import com.quincaisoft.workers.api.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;@RestController public class OperationsController{private final OutboxWorker worker;public OperationsController(OutboxWorker worker){this.worker=worker;}record Request(int limit){}@PostMapping("/api/v1/operations/outbox/project-audit")@PreAuthorize("hasAnyAuthority('operations:manage','SCOPE_operations:manage')")public OutboxWorker.Result process(@RequestBody Request request){return worker.projectAudit(request.limit());}}